    await waitForElementToBeRemoved(() => screen.getByTestId('page-loading'));

    // Header
    screen.getByRole('heading', {
      level: 1,
      name: i18next.t<string>('itGov:taskList.heading')
    });

    // Crumb back to it gov home
    expect(
      getByRoleWithNameTextKey('link', 'itGov:itGovernance')
    ).toHaveAttribute('href', '/system/making-a-request');

    // Sidebar back to home
    expect(
      getByRoleWithNameTextKey('link', 'itGov:button.saveAndExit')
    ).toHaveAttribute('href', '/system/making-a-request');

    // First task list item
    screen.getByRole('heading', {
      level: 3,
      name: i18next.t<string>('itGov:taskList.step.intakeForm.title')
    });
  });

  it('renders closed state - no decision', async () => {
    renderTaskList({
      ...taskListState.bizCaseDraftNotStarted.systemIntake,
      state: SystemIntakeState.CLOSED
    });

    await waitForElementToBeRemoved(() => screen.getByTestId('page-loading'));

    // Closed alert should render
    expect(screen.getByTestId('closed-alert')).toBeInTheDocument();

    const draftBusinessCaseStep = screen.getByTestId(
      'prepare-a-draft-business-case'
    );

    // Start button should be disabled
    expect(
      within(draftBusinessCaseStep).getByRole('button', { name: 'Start' })
    ).toBeDisabled();

    // Status tag should be gray
    expect(
      within(draftBusinessCaseStep).getByTestId('task-list-task-tag')
    ).toHaveClass('bg-base-light');
  });

  it('renders closed state - decision issued', async () => {
    renderTaskList(taskListState.decisionAndNextStepsDone.systemIntake);

    await waitForElementToBeRemoved(() => screen.getByTestId('page-loading'));

    // Decision alert should render
    expect(screen.getByTestId('decision-alert')).toBeInTheDocument();

    // If decision has been made, closed alert should not be displayed
    expect(screen.queryByTestId('closed-alert')).toBeNull();
  });

  it('shows a start button when the intake form has not been started', async () => {
    renderTaskList(taskListState.intakeFormNotStarted.systemIntake);

    await waitForElementToBeRemoved(() => screen.getByTestId('page-loading'));

    const intakeFormStep = screen.getByTestId(
      'fill-out-the-intake-request-form'
    );

    // Start button should be rendered
    expect(
      within(intakeFormStep).getByRole('button', { name: 'Start' })
    ).toBeInTheDocument();
  });

  it('shows a continue button when the intake form is in progress', async () => {
    renderTaskList(taskListState.intakeFormInProgress.systemIntake);

    await waitForElementToBeRemoved(() => screen.getByTestId('page-loading'));

    const intakeFormStep = screen.getByTestId(
      'fill-out-the-intake-request-form'
    );

    // Continue button should be rendered
    expect(
      within(intakeFormStep).getByRole('button', { name: 'Continue' })
    ).toBeInTheDocument();
  });

  it('allows the user to remove their request', async () => {
    renderTaskList(taskListState.intakeFormNotStarted.systemIntake);

    await waitForElementToBeRemoved(() => screen.getByTestId('page-loading'));

    // Remove request button should be shown
    expect(
      screen.getByRole('button', { name: 'Remove your request' })
    ).toBeInTheDocument();

    // Click the remove request button
    userEvent.click(
      screen.getByRole('button', { name: 'Remove your request' })
    );

    // Withdraw modal should open
    expect(
      screen.getByText('Confirm you want to remove this request.')
    ).toBeInTheDocument();

    // Cancel should close the modal
    userEvent.click(screen.getByRole('button', { name: 'Cancel' }));
    expect(
      screen.queryByText('Confirm you want to remove this request.')
    ).toBeNull();
  });
});

