package storage

import (
	"context"

	"github.com/jmoiron/sqlx"

	"github.com/cmsgov/easi-app/pkg/appcontext"
)

// newTransaction begins a new database transaction on the store's underlying connection
func newTransaction(ctx context.Context, db *sqlx.DB) (*sqlx.Tx, error) {
	transaction, err := db.BeginTxx(ctx, nil)
	if err != nil {
		appcontext.ZLogger(ctx).Error("Failed to begin transaction")
		return nil, err
	}
	return transaction, nil
}

// namedPreparer is implemented by anything that can prepare a named statement,
// including both *sqlx.DB and *sqlx.Tx
type namedPreparer interface {
	PrepareNamed(query string) (*sqlx.NamedStmt, error)
}

// prepareNamed prepares a named statement against the given database handle or
// transaction so it can be executed with named parameters later
func prepareNamed(db namedPreparer, query string) (*sqlx.NamedStmt, error) {
	return db.PrepareNamed(query)
}

