//go:embed SQL/trb_request_attendee_create.sql
var trbRequestAttendeeCreateSQL string

// CreateTRBRequestAttendee creates a new TRB request attendee record in the database
func (s *Store) CreateTRBRequestAttendee(ctx context.Context, attendee *models.TRBRequestAttendee) (*models.TRBRequestAttendee, error) {
	attendee.ID = uuid.New()
	stmt, err := prepareNamed(s.db, trbRequestAttendeeCreateSQL)

	if err != nil {
		appcontext.ZLogger(ctx).Error(
			fmt.Sprintf("Failed to update TRB create attendee %s", err),
			zap.String("id", attendee.ID.String()),
		)
		return nil, err
	}

	created := models.TRBRequestAttendee{}
	err = stmt.Get(&created, attendee)

	if err != nil {
		appcontext.ZLogger(ctx).Error("Failed to create TRB request attendee with error %s", zap.Error(err))
		return nil, err
	}
	return &created, nil
}

// CreateTRBRequest creates a new TRBRequest record, along with its initial form and the requester
// attendee, all within a single database transaction
func (s *Store) CreateTRBRequest(ctx context.Context, trb *models.TRBRequest, attendee *models.TRBRequestAttendee) (*models.TRBRequest, error) {
	transaction, err := newTransaction(ctx, s.db)
	if err != nil {
		appcontext.ZLogger(ctx).Error("Failed to begin transaction")
		return nil, err
	}
	defer transaction.Rollback()

	if trb.ID == uuid.Nil {
		trb.ID = uuid.New()
	}

	trbStmt, err := prepareNamed(transaction, trbRequestCreateSQL)
	if err != nil {
		appcontext.ZLogger(ctx).Error(
			fmt.Sprintf("Failed to create trb request with error %s", err),
			zap.String("user", trb.CreatedBy),
		)
		return nil, err
	}
	retTRB := models.TRBRequest{}

	err = trbStmt.Get(&retTRB, trb)
	if err != nil {
		appcontext.ZLogger(ctx).Error(
			fmt.Sprintf("Failed to create trb request with error %s", err),
			zap.String("user", trb.CreatedBy),
		)
		return nil, err
	}

	form := models.TRBRequestForm{
		TRBRequestID: retTRB.ID,
		Status:       models.TRBFormStatusReadyToStart,
		CollabGroups: pq.StringArray{},
	}
	form.ID = uuid.New()
	form.CreatedBy = retTRB.CreatedBy

	formStmt, err := prepareNamed(transaction, trbRequestFormCreateSQL)
	if err != nil {
		appcontext.ZLogger(ctx).Error(
			fmt.Sprintf("Failed to update TRB create form %s", err),
			zap.String("id", form.ID.String()),
		)
		return nil, err
	}

	created := models.TRBRequestForm{}
	err = formStmt.Get(&created, form)
	if err != nil {
		appcontext.ZLogger(ctx).Error("Failed to create TRB request form with error %s", zap.Error(err))
		return nil, err
	}

	attendee.ID = uuid.New()
	attendee.TRBRequestID = retTRB.ID
	if attendee.CreatedBy == "" {
		attendee.CreatedBy = retTRB.CreatedBy
	}

	attendeeStmt, err := prepareNamed(transaction, trbRequestAttendeeCreateSQL)
	if err != nil {
		appcontext.ZLogger(ctx).Error(
			fmt.Sprintf("Failed to create trb request attendee with error %s", err),
			zap.String("user", attendee.CreatedBy),
		)
		return nil, err
	}

	createdAttendee := models.TRBRequestAttendee{}
	err = attendeeStmt.Get(&createdAttendee, attendee)
	if err != nil {
		appcontext.ZLogger(ctx).Error(
			fmt.Sprintf("Failed to create trb request attendee with error %s", err),
			zap.String("user", attendee.CreatedBy),
		)
		return nil, err
	}

	err = transaction.Commit()
	if err != nil {
		appcontext.ZLogger(ctx).Error("Failed to create TRB request with error %s", zap.Error(err))
		return nil, err
	}

	return &retTRB, nil
}

